-- 0. СТВОРЕННЯ БАЗИ CREATE DATABASE CakesDB; GO  -- 1. ТАБЛИЦІ  CREATE TABLE Clients (  id INT PRIMARY KEY IDENTITY(1,1),     surname VARCHAR(50) NOT NULL,     firstname VARCHAR(50) NOT NULL,     phone VARCHAR(20),     email VARCHAR(50) UNIQUE,     address VARCHAR(100) );  CREATE TABLE PastryChefs (     id INT PRIMARY KEY IDENTITY(1,1),     fullname VARCHAR(100) NOT NULL,     position VARCHAR(50),     work_experience INT CHECK (work_experience >= 0),     phone VARCHAR(20),     CONSTRAINT UQ_PastryChefs UNIQUE (fullname, phone) );  CREATE TABLE Orders (     id INT PRIMARY KEY IDENTITY(1,1),     order_number INT UNIQUE,     order_date DATE DEFAULT GETDATE(),     completion_date DATE,     status VARCHAR(20) DEFAULT 'new',     CONSTRAINT CHK_Status CHECK (status IN ('new','in_progress','done')),     total_cost DECIMAL(10,2),     paid_amount DECIMAL(10,2) DEFAULT 0,     client_id INT NOT NULL,     chef_id INT NOT NULL,     FOREIGN KEY (client_id) REFERENCES Clients(id),     FOREIGN KEY (chef_id) REFERENCES PastryChefs(id) ); ALTER TABLE Orders ADD paid_amount DECIMAL(10,2) DEFAULT 0;  CREATE TABLE Cakes (     id INT PRIMARY KEY IDENTITY(1,1),     name VARCHAR(50),     type VARCHAR(50),     weight DECIMAL(10,2),     tiers INT,     design_description VARCHAR(200),     order_id INT,     FOREIGN KEY (order_id) REFERENCES Orders(id) );  CREATE TABLE Ingredients (     id INT PRIMARY KEY IDENTITY(1,1),     name VARCHAR(50),     unit VARCHAR(10),     price_per_unit DECIMAL(10,2) );  CREATE TABLE Recipe (     cake_id INT,     ingredient_id INT,     quantity DECIMAL(10,2),     PRIMARY KEY (cake_id, ingredient_id),     FOREIGN KEY (cake_id) REFERENCES Cakes(id),     FOREIGN KEY (ingredient_id) REFERENCES Ingredients(id) );  CREATE TABLE Payments (     id INT PRIMARY KEY IDENTITY(1,1),     payment_number INT UNIQUE,     payment_date DATE DEFAULT GETDATE(),     amount DECIMAL(10,2),     payment_type VARCHAR(20),     order_id INT NOT NULL,     FOREIGN KEY (order_id) REFERENCES Orders(id) );   -- 2. ДАНІ  INSERT INTO Clients (surname, firstname, phone, email, address) VALUES  ('Іваненко', 'Оля', '123456789', 'olya@gmail.com', 'Львів'), ('Шевченко', 'Стефанія', '467583746', 'stef@gmail.com', 'Івано-Франківськ'), ('Бусь', 'Сергій', '883026783', 'serg@gmail.com', 'Тернопіль'), ('Дружня', 'Оксана', '124677680', 'oks@gmail.com', 'Ужгород'), ('Петренко', 'Ігор', '987654321', 'igor@gmail.com', 'Київ');  INSERT INTO PastryChefs (fullname, position, work_experience, phone) VALUES ('Марія Коваль', 'Кондитер', 5, '500475674'), ('Христина Успенко', 'Кондитер', 3, '274604750'), ('Артур Захаренко', 'Кондитер', 2, '465790734'), ('Олег Бойко', 'Шеф-кондитер', 7, '442227568');  INSERT INTO Ingredients (name, unit, price_per_unit) VALUES ('Борошно','кг',30), ('Цукор','кг',50), ('Вершки','л',70), ('Асорті ягід','кг',90), ('Масло','кг',200), ('Тропічні фрукти','кг',120), ('Мед','л',100), ('Олія','л',80), ('Шоколад','кг',100);  INSERT INTO Orders (order_number, order_date, completion_date, status, total_cost, client_id, chef_id) VALUES (1,'2024-04-15','2024-05-03','done',1500,1,2), (2,'2024-06-03','2024-06-20','in_progress',800,2,1), (3,'2024-06-01','2024-06-11','in_progress',900,3,1), (4,'2024-06-07','2024-06-17','in_progress',700,4,3), (5,'2024-05-02','2024-05-05','done',1800,5,4);  INSERT INTO Cakes (name,type,weight,tiers,design_description,order_id) VALUES ('Шоколадний','весільний',3,2,'квіти',1), ('Снікерс','святковий',2.5,2,'день народження',2), ('Тропічна насолода','святковий',1,1,'картинка',3), ('Рафаелло','святковий',1.5,1,'крем',4), ('Снікерс дитячий','дитячий',2,1,'мультфільм',5);  INSERT INTO Recipe (cake_id, ingredient_id, quantity) VALUES (1,1,2),(1,2,0.9),(1,3,1),(1,5,0.5),(1,7,0.5),(1,8,2), (2,1,1.5),(2,2,0.8),(2,3,0.8),(2,5,0.4),(2,7,0.4),(2,8,1), (3,1,0.5),(3,2,0.4),(3,3,0.3),(3,5,0.1),(3,7,0.1),(3,8,0.5), (4,1,0.8),(4,2,0.5),(4,3,0.4),(4,5,0.2),(4,7,0.2),(4,8,0.5), (5,1,1),(5,2,0.6),(5,3,0.7),(5,5,0.3),(5,7,0.3),(5,8,0.5);  INSERT INTO Payments (